import 'dart:convert';
import 'dart:typed_data';

class SampleFoodImages {
  static final Uint8List healthyBowl = base64Decode('');
  static final Uint8List phoBo = base64Decode('');
  static final Uint8List banhMi = base64Decode('');

  static Uint8List getByKey(String key) {
    switch (key) {
      case 'pho_bo':
        return phoBo;
      case 'banh_mi':
        return banhMi;
      case 'healthy_bowl':
      default:
        return healthyBowl;
    }
  }
}